# -*- coding: utf-8 -*-
S = "сверка по рисункам и ответам учебников (отрендеренные страницы Нелина 11 и OCR Алимова 9), 30.09"
P = {}
def E(t, why, **kw): P[t] = dict(src=S, why=why, **kw)
NEL = "по рис. 2.11 учебника (Нелин, 11 кл., § 2, упр. 10): "
E("G11_TB_§2_10_1", NEL + "$s(2)=2$, $s(3)=4$, средняя скорость $\\frac{4-2}{1}=2$ — ключ верен; объяснения неверных вариантов переписаны",
  dnew={0: ("$1{,}5$", "Ученик усреднил скорости на двух участках вместо отношения приращения пути к приращению времени."),
        1: ("$4$", "Ученик взял значение пути $s(3)=4$ вместо приращения $s(3)-s(2)$."),
        2: ("$1$", "Ученик взял приращение пути на части промежутка, а не на всём отрезке от $2$ до $3$.")})
E("G11_TB_§2_10_2", NEL + "в момент $t=3$ график имеет максимум (горизонтальная касательная, $v(3)=0$), а при $t=2$ путь растёт ($v(2)>0$) — ключ верен; объяснения неверных вариантов переписаны",
  dnew={0: ("$v(2) < v(3)$", "Ученик решил, что скорость больше там, где больше значение пути $s(t)$."),
        1: ("$v(2) = v(3)$", "Ученик решил, что на участке от $2$ до $3$ график почти прямой, и приравнял скорости, не сравнив наклоны касательных."),
        2: ("$v(2) = 0$", "Ученик перепутал: горизонтальная касательная (скорость $0$) в точке $t=3$, а не в $t=2$.")})
E("G11_TB_§2_10_3", NEL + "график $s(t)$ достигает максимума при $t=3$ и затем убывает, поэтому направление движения меняется в момент $t=3$ (в ключе стояло $t=4$ — правый конец графика)",
  k="да, $t=3$",
  dnew={0: ("нет", "Ученик решил, что направление меняется только при $s=0$."),
        1: ("да, $t = 2$", "Ученик принял за разворот точку $t=2$, где график лишь круче всего идёт вверх."),
        2: ("да, $t = 4$", "Ученик взял правый конец графика $t=4$, а не точку максимума $t=3$.")})
E("G11_TB_§2_11_1", "по рис. 2.12 (Нелин, 11 кл., § 2, упр. 11): касательная горизонтальна в точках $x=-3$ (максимум), $x=-1$ (минимум) и $x=4$ (график касается оси $Ox$); в ключе стояло $x=-2,2,5$",
  k="$x = -3$, $x = -1$, $x = 4$",
  dnew={0: ("$x = -4$, $x = 7$", "Ученик решил, что на концах промежутка производная равна нулю."),
        1: ("$x = -3$, $x = -1$", "Ученик нашёл точки экстремума, но пропустил точку $x=4$ с горизонтальной касательной."),
        2: ("$x = 1$, $x = 5$", "Ученик указал точки излома и возврата, в которых производная не существует, а не равна нулю.")})
E("G11_TB_§2_11_2", "по рис. 2.12: производная не существует в точке излома $x=1$ и в точке возврата $x=5$; касательной к графику в них нет; в ключе стояло $x=-1$, $x=4$",
  k="$x = 1$, $x = 5$; касательной к графику в этих точках нет ($x=1$ — излом, $x=5$ — точка возврата)",
  dnew={0: ("$x = 1$, $x = 5$; в обеих точках касательная существует", "Ученик решил, что раз график непрерывен, касательная в этих точках есть."),
        1: ("$x = 1$, $x = 5$; в точке $x = 1$ касательная существует, в точке $x = 5$ нет", "Ученик принял излом за гладкую точку."),
        2: ("$x = -3$, $x = -1$, $x = 4$; касательная существует во всех этих точках", "Ученик указал точки, где производная равна нулю (касательная горизонтальна), а не где она не существует.")})
E("G9_TB_УКГ3_330_2", "по учебнику (Алимов, 9 кл., № 330(2)) ответ 2; напечатанное «$\\cos3{,}5$» — потеря $\\pi$ (при $\\cos3{,}5\\pi=0$: $1-(-1)+0=2$); условие приведено к виду $\\cos3{,}5\\pi$, остальные пункты упражнения — с $\\pi$",
  q=r"Вычислите: $\cos 0 - \cos 3\pi + \cos 3{,}5\pi$", k="$2$",
  dnew={0: ("$0$", r"Ученик принял $\cos3\pi=1$: $1-1+0=0$."),
        1: ("$3$", r"Ученик принял $\cos3{,}5\pi=1$: $1+1+1=3$."),
        2: ("$1$", r"Ученик принял $\cos3\pi=0$: $1-0+0=1$.")})
E("G9_TB_УКГ3_326_2", "по учебнику (Алимов, 9 кл., № 326(2)) ответ 0; в условии два одинаковых слагаемых «$\\tg\\frac{5\\pi}{12}+\\tg\\frac{5\\pi}{12}$» — искажение: по тождеству $\\tg\\alpha+\\tg\\beta=\\frac{\\sin(\\alpha+\\beta)}{\\cos\\alpha\\cos\\beta}$ ответ 0 при $\\alpha+\\beta=\\pi$, т. е. $\\tg\\frac{5\\pi}{12}+\\tg\\frac{7\\pi}{12}$ (как в пунктах 1 и 3: $267^\\circ+93^\\circ$, $99^\\circ+81^\\circ$ — суммы $360^\\circ$ и $180^\\circ$)",
  q=r"Докажите тождество и вычислите $\operatorname{tg}\alpha+\operatorname{tg}\beta=\dfrac{\sin(\alpha+\beta)}{\cos\alpha\cdot\cos\beta}$: $\operatorname{tg}\dfrac{5\pi}{12}+\operatorname{tg}\dfrac{7\pi}{12}$", k="$0$",
  dnew={0: (r"$4 + 2\sqrt{3}$", r"Ученик принял $\tg\dfrac{7\pi}{12}=\tg\dfrac{5\pi}{12}$ и сложил два одинаковых слагаемых."),
        1: ("$4$", r"Ученик принял $\tg\dfrac{7\pi}{12}=2-\sqrt{3}$ (тангенс $15^\circ$) вместо $-(2+\sqrt{3})$."),
        2: ("$2$", r"Ученик принял оба тангенса равными $1$ (как $\tg\dfrac{\pi}{4}$).")})
